#pragma once 
// Per-node (Design A) kernel API: each _node function does one surface 
// node's work; producers RETURN their force contribution (the dispatch 
// sums them in a register), the Lax _node functions take that alpha by 
// value and return |alpha| for the caller's CFL reduction, finalized by 
// the _cfl functions. 
